import pandas as pd
import numpy as np
import copy


def generate_test_case(test_case_id):
    def generate_ans(data):
        df = data
        sh = 0
        min_R2 = 0
        for i in range(len(df)):
            min_R2 += (df["#1"].iloc[i] - df["#2"].iloc[i]) ** 2
        for i in range(len(df)):
            R2 = 0
            for j in range(len(df)):
                R2 += (df["#1"].iloc[j] - df["#2"].iloc[j]) ** 2
            if min_R2 > R2:
                sh = i
                min_R2 = R2
            df["#1"] = np.roll(df["#1"], shift=1)
        df["#1"] = np.roll(df["#1"], shift=sh)
        return df

    def define_test_input(test_case_id):
        if test_case_id == 1:
            df = pd.DataFrame(
                {
                    "#1": [11.6985, 43.6431, 54.9089, 63.1225, 72.4399],
                    "#2": [126.0, 134.0, 130.0, 126.0, 120.0],
                },
                index=[
                    "1980-01-01",
                    "1980-01-02",
                    "1980-01-03",
                    "1980-01-04",
                    "1980-01-05",
                ],
            )
        elif test_case_id == 2:
            df = pd.DataFrame(
                {"#1": [45, 51, 14, 11, 14], "#2": [126.0, 134.0, 130.0, 126.0, 120.0]},
                index=[
                    "1980-01-01",
                    "1980-01-02",
                    "1980-01-03",
                    "1980-01-04",
                    "1980-01-05",
                ],
            )
        return df

    test_input = define_test_input(test_case_id)
