import pandas as pd
import numpy as np
import copy


def generate_test_case(test_case_id):
    def generate_ans(data):
        df = data
        return (
            df.groupby("key1")["key2"]
            .apply(lambda x: (x == "one").sum())
            .reset_index(name="count")
        )

