            ]
        elif test_case_id == 2:
            a = [
                np.array([np.nan, 2, 3]),
                np.array([1, np.nan, 3]),
                np.array([1, 2, 3]),
            ]
        elif test_case_id == 3:
            a = [np.array([10, 2, 3]), np.array([1, 9, 3]), np.array([1, 6, 3])]
        elif test_case_id == 4:
            a = [np.array([10, 4, 3]), np.array([1, np.nan, 3]), np.array([8, 6, 3])]
        elif test_case_id == 5:
            a = [
                np.array([np.nan, np.nan]),
                np.array([np.nan, np.nan]),
                np.array([np.nan, np.nan]),
